import React, { useState } from 'react';
import { useDropzone } from 'react-dropzone';
import {
  Container,
  Paper,
  Typography,
  Button,
  Box,
  CircularProgress,
  List,
  ListItem,
  ListItemText,
} from '@mui/material';
import axios from 'axios';

interface AnalysisResponse {
  insights: string;
  discrepancies: string[];
}

function App() {
  const [files, setFiles] = useState<File[]>([]);
  const [analysis, setAnalysis] = useState<AnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop: (acceptedFiles: File[]) => {
      setFiles(prevFiles => [...prevFiles, ...acceptedFiles]);
      setError(null);
    },
    accept: {
      'application/pdf': ['.pdf'],
      'image/*': ['.png', '.jpg', '.jpeg']
    },
    multiple: true
  });

  const handleRemoveFile = (index: number) => {
    setFiles(prevFiles => prevFiles.filter((_, i) => i !== index));
  };

  const handleAnalyze = async () => {
    if (files.length < 2) {
      setError('Please upload at least 2 documents');
      return;
    }

    setLoading(true);
    setError(null);

    const formData = new FormData();
    files.forEach((file: File) => {
      formData.append('files', file);
    });

    try {
      const response = await axios.post<AnalysisResponse>('http://localhost:8000/api/analyze-documents', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });
      setAnalysis(response.data);
    } catch (err) {
      if (axios.isAxiosError(err)) {
        setError(`Error analyzing documents: ${err.response?.data?.detail || err.message}`);
      } else {
        setError('Error analyzing documents. Please try again.');
      }
      console.error('Error details:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Container maxWidth="md" sx={{ py: 4 }}>
      <Typography variant="h4" component="h1" gutterBottom align="center">
        Trade Document Analyzer
      </Typography>

      <Paper
        {...getRootProps()}
        sx={{
          p: 3,
          mb: 3,
          textAlign: 'center',
          backgroundColor: isDragActive ? '#f0f8ff' : '#fff',
          border: '2px dashed #ccc',
          cursor: 'pointer',
        }}
      >
        <input {...getInputProps()} />
        <Typography>
          {isDragActive
            ? 'Drop the files here...'
            : 'Drag and drop documents here, or click to select files'}
        </Typography>
      </Paper>

      {files.length > 0 && (
        <Box sx={{ mb: 3 }}>
          <Typography variant="h6" gutterBottom>
            Selected Files:
          </Typography>
          <List>
            {files.map((file: File, index: number) => (
              <ListItem 
                key={index}
                secondaryAction={
                  <Button 
                    color="error" 
                    onClick={() => handleRemoveFile(index)}
                  >
                    Remove
                  </Button>
                }
              >
                <ListItemText primary={file.name} />
              </ListItem>
            ))}
          </List>
        </Box>
      )}

      <Box sx={{ display: 'flex', justifyContent: 'center', mb: 3 }}>
        <Button
          variant="contained"
          onClick={handleAnalyze}
          disabled={files.length < 2 || loading}
        >
          {loading ? <CircularProgress size={24} /> : 'Analyze Documents'}
        </Button>
      </Box>

      {error && (
        <Typography color="error" sx={{ mb: 2 }}>
          {error}
        </Typography>
      )}

      {analysis && (
        <Paper sx={{ p: 3 }}>
          <Typography variant="h6" gutterBottom>
            Analysis Results
          </Typography>

          <Typography variant="subtitle1" gutterBottom>
            Insights:
          </Typography>
          <Typography paragraph>
            {analysis.insights}
          </Typography>

          <Typography variant="subtitle1" gutterBottom>
            Discrepancies:
          </Typography>
          <List>
            {analysis.discrepancies.map((discrepancy: string, index: number) => (
              <ListItem key={index}>
                <ListItemText primary={discrepancy} />
              </ListItem>
            ))}
          </List>
        </Paper>
      )}
    </Container>
  );
}

export default App;
